insert into public.okr_cycles (id, kind, title, year, month, week_no, start_date, end_date, parent_id, goals, feedback) values
  ('2026-08', 'month', 'CS팀 8월 OKR 실행결과', 2026, 8, null, '2026-08-01', '2026-08-31', null, $okr$[{"no": 1, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 1", "objective": "AI를 활용해 CS 반복업무 또는 데이터 업무 중 1건 이상을 실제로 개선하고, 개선 전과 개선 후의 시간 차이를 확인한다.", "criteria": "• 개선 대상 선정(7월 접수 개선항목 또는 자동화 가능 업무 중): 1건 이상  [건수형]\n• 실제 업무 적용률: 100%\n• 개선 전/후 소요시간 측정 완료율: 100%\n• 결과 기록(개선 전 → 개선 후 → 단축시간 → 추가개선점) 완료율: 100%\n• [차월반영] 추가 개선점을 9월 개선항목으로 이관: 1건 이상  [건수형]"}, {"no": 2, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 2", "objective": "재방문·중복방문·장시간 처리 건을 월 1회 분석하고, 원인과 다음 개선안을 작성한다.", "criteria": "• 8월 재방문·중복방문·장시간 처리건 취합률: 100%\n• 분석양식(업체명/발생사유/처리시간/재방문여부/원인/개선안) 적용률: 100%\n• 파트별 대표사례 선정: 1건 이상  [건수형]\n• 원인 규명 및 개선안 작성률: 100%\n• 7월 선정사례 대비 동일유형 반복여부 확인: 완료  [건수형]"}, {"no": 3, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 3", "objective": "파트별 비용절감 또는 효율개선 아이디어를 월 1건 이상 제출하고, 실행 가능한 아이디어를 실제 적용한다.", "criteria": "• 파트별 아이디어 제출: 1건 이상  [건수형]\n• 서식(현재문제/개선방법/예상효과) 준수율: 100%\n• 실행가능 아이디어 선정 및 실제 적용: 1건 이상  [건수형]\n• 실행결과(실행 전 문제/실행 후 변화/절감 시간·비용) 기록률: 100%\n• 실행 불가 아이디어의 불가 사유 기록률: 100% (해당 시)"}, {"no": 4, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 1", "objective": "초과 사용 업체 대상 제안 방문을 월 2건 이상 진행하고, 방문 후 후속 관리를 한다.", "criteria": "• 8월 초과사용 업체 리스트 확인률: 100%\n• 선정기준(초과사용량/초과금액/계약갱신 가능성 중 2가지 이상 해당) 충족 업체 선정률: 100%\n• 제안 방문: 2건 이상  [건수형]\n• 방문기록(제안내용/고객반응/다음액션) 작성률: 100%\n• 후속 필요 업체의 담당자·진행일정·다음연락시점 수립률: 100%"}, {"no": 5, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 2", "objective": "8월 PC·IT 관리 테마를 정해 고객에게 홍보하고, 고객 반응을 기록한다.", "criteria": "• 8월 홍보테마 선정: 1개  [건수형]\n• 홍보자료·안내멘트 준비: 1개 이상  [건수형]\n• 고객반응 3분류 기록률: 100%\n     └ 필수 기재 → 관심 있음 ○건 / 추후 검토 ○건 / 필요 없음 ○건\n• 파트별 홍보사례 공유: 1건 이상  [건수형]\n• [차월반영] 반응 좋았던 멘트 타 파트 공유: 1건 이상  [건수형]"}, {"no": 6, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 3", "objective": "계약 완료 건은 계약서 작성 확인까지 100% 완료한다.", "criteria": "• 계약완료 건 대비 계약서 작성 확인률: 100%\n• 발송 후 1주일(7일) 이내 작성완료 여부 확인 이행률: 100%\n• 미작성 건 주1회 재확인 이행률: 100%\n• 월말 대사(계약완료 건수 vs 계약서 작성완료 건수) 완료  [건수형]\n• 누락 건 업체명·누락사유·다음조치 기록률: 100% (해당 시)"}, {"no": 7, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 1", "objective": "IT 레벨 3 실습을 이어가고, PC·IT 처리 사례를 월 1건 이상 공유한다.", "criteria": "• 파트별 주1회 학습/실습 진행률: 100% (4주/4주)\n• 월1회 IT 레벨3 체크리스트 진행상황 확인: 완료  [건수형]\n• PC·IT 처리사례 공유: 1건 이상  [건수형]\n• 사례 형식(현장문제/조치방법/결과/배운점) 준수율: 100%\n• [차월반영] 어려웠던 사례를 9월 교육주제로 등록: 1건 이상  [건수형]"}, {"no": 8, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 2", "objective": "각 인원이 주 2개 이상 블로그 답글을 작성하고, 참여 현황을 꾸준히 유지한다.", "criteria": "• 인당 주 답글: 2개 이상\n• 인원별 주2개 달성 참여율: 100% (미달 시 인원별 실적 기재)\n• 주1회 파트 현황확인 이행률: 100% (4주/4주)\n• 월말 인원별·파트별 답글 수 집계: 완료  [건수형]\n• 무의미·반복 댓글: 0건"}, {"no": 9, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 3", "objective": "소통 문제와 디브리핑 누락 사례를 확인하고, 부파트장 주관 회식을 진행하거나 일정을 확정한다.", "criteria": "• 업무전달 후 이해 재확인 이행률: 100%\n• 파트별 주간 병목현상 점검: 4주/4주\n• 월1회 소통·디브리핑 누락사례 확인: 완료  [건수형]\n• 누락사례 원인 및 개선안 작성률: 100% (해당 시)\n• 부파트장 주관 회식: 8월 진행 완료 또는 9월 전 일정 확정  [건수형]"}]$okr$::jsonb, $okr${"3": {"action": "B", "memo": "1.대상: A파트 부분달성 / B파트 미착수\n\n2. 8월 피드백\n• A: 아이디어 1건은 제출했으나 9월 적용 예정으로, 8월 실제 적용과 효과 확인이 완료되지 않음.\n• B: 아이디어 0건으로 선정·실행·결과 기록까지 이어지지 못함.\n\n3. 9월 개선 방향\n① A: 점검·AS변환기 자가요청란 +/- 기능의 개발 담당자와 적용일을 확정한다. 여러 기종용 자유입력란을 유지하고 실제 요청·출고 과정에서 기능을 확인한다.\n② B: 파트원 의견을 취합해 현재문제·개선방법·예상효과를 갖춘 아이디어 1건 이상을 선정하고, 9월 중 실행 가능한 범위로 정해 적용한다.\n③ 적용 전 오류 건수·확인 소요시간을 기록하고, 적용 후 같은 업무·기간 기준으로 비교한다. 예상효과와 실제 결과를 구분한다.\n\n4. 담당·점검 제안\n• 파트장 또는 부파트장: 실행 담당자·적용일·검증방법 지정 및 매주 진행 확인. 파트장: 지연 사유와 지원 필요사항 조정.\n5. 완료 기준\n• 파트별 1건 이상 실제 적용, 적용일·사용 결과 및 전후 변화 기록. 9월 말까지 미적용이면 사유·다음 적용일을 명시한다."}, "4": {"action": "B", "memo": "1. 대상: A·D파트 부분달성 / B파트 미흡\n\n2. 8월 피드백\n• A: 리스트 확인 50%, 제안 방문 1건/목표 2건. AS·미수 업무로 대상 관리가 부족함.\n• B: 리스트 30곳 확인 후 1곳만 선정, 방문 0건. “근처 일정 시 방문”으로 남겨 실행 일정이 확정되지 않음.\n• D: 리스트 7곳·대상 3곳 확인 후 방문 0건. 기기 교체 대응으로 상담이 이월됐고 선정 근거·후속 일정도 부족함.\n\n3. 9월 개선 방향\n① 각 파트는 확인 대상·완료 건수를 기록하고, 대상 최소 2곳의 선정 근거와 내부 담당자·방문일·다음 연락일을 확정한다.\n② A: 포레스트병원 외 추가 업체를 선정한다. \nB: 부촌가로주택정비사업과 추가 1곳의 방문을 예약한다. \nD: 선정 3곳의 근거를 보완하고 대치깊은생각수학학원 초과료·기본료 상담일을 확정한다.\n③ 캘린더에 제안 방문을 별도로 등록한다. AS 방문이 있어도 초과사용 제안을 실제 진행했는지 구분한다.\n④ 방문 당일 제안내용·고객반응·다음 조치를 기록하고, 후속 필요 업체는 담당자·일정·다음 연락일까지 정한다.\n\n4. 담당·점검 제안\n• 부파트장: 매주 미방문 업체 확인 및 일정 재배정. 파트장: AS 일정과 충돌 시 지원·동선 조정.\n\n5. 완료 기준\n• 9월 파트별 제안 방문 2건 이상, 방문기록 100%, 후속 필요 업체 계획 100%. 포레스트병원은 후속 필요 여부를 별도 판단한다."}, "5": {"action": "C", "memo": "1. 대상: A·B파트 부분달성 / C파트 미흡\n\n2. 8월 피드백\n• A: 반응 기록 17/20건=85%, 미기록 3건. B: 12/20건=60%, 미기록 8건. C: 39/80건=48.75%, 미기록 41건.\n• 세 파트 합계 미기록은 3+8+41=52건. 홍보자료 준비 후 반응 기록·사례와 멘트 공유까지 연결되지 못함.\n\n3. 9월 개선 방향\n① 8월 미기록 52건은 담당자가 기존 상담 기록으로 확인한다. 확인할 수 없는 반응은 추정하지 말고 미확인으로 남긴다.\n② 9월 홍보 직후 업체명·홍보일·담당자와 관심 있음/추후 검토/필요 없음 중 실제 반응을 기록한다. 즉시 분류할 수 없으면 재확인 일정도 남긴다.\n③ 각 파트는 매주 전체 홍보 건수와 3분류 합계를 비교해 누락 업체를 지정하고 해당 담당자가 보완하도록 한다.\n④ 각 파트는 실제 홍보사례 1건과 안내멘트 1건을 선정한다. 파트 내 사례 공유와 타 파트 멘트 공유는 대상·게시일·내용을 구분하여 기록한다.\n⑤ 관심·추후 검토 업체는 고객 의사를 확인해 다음 연락일 또는 본사 연결 여부를 정한다.\n\n4. 담당·점검 제안\n• 현장 담당자: 당일 기록. 부파트장: 주간 누락 확인. 파트장: 월말 집계와 공유 실적 확인.\n\n5. 완료 기준\n• 고객반응 기록률 100%, 파트별 사례 공유 1건 이상 및 안내멘트 공유 1건 이상. 공유 계획만으로 완료 처리하지 않는다."}, "6": {"action": "", "memo": "1. 대상: A·B·C·D파트 모두 부분달성\n\n2. 8월 피드백\n• A: 제안·계약 완료가 혼재해 확인률 산정이 어렵고 2차 확인 4건이 남음.\n• B: 작성 확인 11/13건=84.6%, 7일 이내 확인 1/13건=7.7%. 전략영업팀 확인 대상은 네오스엠 1곳이며 나머지 지연 원인은 추가 확인 필요.\n• C: 계약완료 5건의 작성 확인은 완료했으나, 관리대상 8건의 기한 내 확인은 4건. 미작성 3건 중 주간 재확인은 2건만 진행함.\n• D: 완료 2건·진행 2건을 구분했으나, 기한 내 확인 일부 미이행과 월말 최종 확인·재확인 기록 부족.\n\n3. 9월 개선 방향\n① 업체별로 제안/계약완료/계약서 발송/작성완료 상태를 구분하고, 각 확인률의 대상 건수를 명확히 한다.\n② 발송 당일 내부 담당자·발송일·7일 이내 확인일을 캘린더에 등록한다. 미작성 건은 다음 확인일을 지정해 주 1회 확인하고 완료 시 카톡방에 회신한다.\n③ A: 2차 확인 4건의 상태·다음 조치 확정. B: 엠에스알·랜드커머스큐브 확인 결과 기록, 네오스엠은 전략영업팀 인계 후 회신 확인.\n④ C: 여름·피플앤드테크놀러지·더스콜라스의 재발송·확인 진행 여부를 점검한다. D: 완료 2건의 작성 여부와 진행 2건의 9월 일정을 확인한다.\n⑤ 이미 지난 예정일은 실행 결과를 먼저 확인하고 미실행이면 다음 연락일을 즉시 다시 정한다.\n\n4. 담당·점검 제안\n• 파트장 또는 부파트장: 매주 기한 초과·미작성 목록 점검. 파트장: 담당부서 미확정 건 조정 및 월말 최종 비교.\n\n5. 완료 기준\n• 해당 대상의 작성 확인·기한 내 확인·주간 재확인 100%, 월말 건수 비교 완료. 누락은 업체명·사유·담당자·다음 조치 기록."}, "7": {"action": "", "memo": "1. 대상: A·C파트 부분달성\n\n2. 8월 피드백\n• A: 레벨 3 진입이 어려워 레벨 1·2 복습으로 방향을 조정함. 기초 보완 활동과 레벨 3 목표 달성 여부를 구분해야 함.\n• C: 주간 학습은 1/4주=25%에 그침. 학습일·담당자 지정이 부족했고, 실제 PC·IT 사례는 발생 0건으로 공유·작성형식은 해당없음.\n\n3. 9월 개선 방향\n① A: 파트회의 후 레벨 1·2 시험·오답 복습을 매주 진행하고 인원별 시험일·점수·반복 오답을 기록한다. 100점 목표와 부족한 영역을 확인한 뒤 레벨 3 시작 가능 시점·준비사항을 정한다.\n② C: 주간 학습일·진행 담당자와 불참 시 보충일을 사전에 지정한다. 기본적인 노트북 점검·조치를 교육하고 학습일·내용·참여인원을 기록한다.\n③ 부파트장은 매주 실제 학습 여부를 확인하고, 파트장은 월 1회 체크리스트와 다음 교육주제를 확인한다.\n④ 현장 사례가 발생하면 문제·조치·결과·배운점 형식으로 공유한다. 발생하지 않으면 0건 확인 근거를 남기고 교육용·과거 사례 학습은 별도 기록한다.\n\n4. 완료 기준\n• 주간 계획 대비 학습 이행률 100%, 월 1회 체크리스트 확인. A는 레벨 3 진행 또는 목표 조정안을 팀장과 확인한다.\n• 실제 사례 0건은 미공유로 감점하지 않으며, 교육용 사례를 신규 현장 실적으로 집계하지 않는다."}, "8": {"action": "", "memo": "1. 대상: C파트 부분달성\n\n2. 8월 피드백\n• 해당 시트에는 7월 답글 1,700건 작성 후 8월 작성 0건으로 기록됨. 전월 누적 기여와 당월 주간 참여는 구분하여 관리해야 함.\n한다.\n\n3. 9월 개선 방향\n① 전월 초과 실적과 별도로 각 인원이 매주 2건 이상 작성한다. 한 시기에 몰아서 작성하지 않고 주차별로 분산한다.\n② 부파트장은 인원별·주차별 작성 건수와 확인일을 기록하고, 미달 인원에게 해당 주 안에 보완하도록 안내한다.\n③ 휴가·업무 일정이 있는 주는 사전에 참여 일정을 조율하고, 현황 확인 담당자의 부재 시 대체 확인자를 지정한다.\n④ 월말에 인원별 합계와 파트 합계를 비교하고, 주간 목표 달성 여부와 무의미·반복 댓글 여부도 함께 확인한다.\n\n3. 담당·점검 제안\n• 파트원: 매주 작성. 파트장 또는 부파트장: 주 1회 실적 확인. 파트장: 월말 집계·미달 사유 검토.\n\n4. 완료 기준\n• 인당 매주 2건 이상, 인원별 주간 참여율 100%, 주간 확인 및 월말 집계 완료. 전월 실적으로 당월 미참여를 대체하지 않는다."}}$okr$::jsonb),
  ('2026-09', 'month', 'CS팀 9월 OKR 실행결과', 2026, 9, null, '2026-09-01', '2026-09-30', null, $okr$[{"no": 1, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 1", "objective": "AI를 활용해 CS 반복업무 또는 데이터 업무 중 1건 이상을 실제로 개선하고, 개선 전과 개선 후의 시간 차이를 확인한다.", "criteria": "• 개선 대상 선정(8월 접수 개선항목 또는 자동화 가능 업무 중): 1건 이상  [건수형]\n• 실제 업무 적용률: 100%\n• 개선 전/후 소요시간 측정 완료율: 100%\n• 결과 기록(개선 전 → 개선 후 → 단축시간 → 추가개선점) 완료율: 100%\n• [차월반영] 추가 개선점을 9월 개선항목으로 이관: 1건 이상  [건수형]"}, {"no": 2, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 2", "objective": "재방문·중복방문·장시간 처리 건을 월 1회 분석하고, 원인과 다음 개선안을 작성한다.", "criteria": "• 8월 재방문·중복방문·장시간 처리건 취합률: 100%\n• 분석양식(업체명/발생사유/처리시간/재방문여부/원인/개선안) 적용률: 100%\n• 파트별 대표사례 선정: 1건 이상  [건수형]\n• 원인 규명 및 개선안 작성률: 100%\n• 7월 선정사례 대비 동일유형 반복여부 확인: 완료  [건수형]"}, {"no": 3, "pillar": "Pillar 1.\nAI · 효율성 · 비용절감", "bottleneck": "병목현상 3", "objective": "파트별 비용절감 또는 효율개선 아이디어를 월 1건 이상 제출하고, 실행 가능한 아이디어를 실제 적용한다.", "criteria": "• 파트별 아이디어 제출: 1건 이상  [건수형]\n• 서식(현재문제/개선방법/예상효과) 준수율: 100%\n• 실행가능 아이디어 선정 및 실제 적용: 1건 이상  [건수형]\n• 실행결과(실행 전 문제/실행 후 변화/절감 시간·비용) 기록률: 100%\n• 실행 불가 아이디어의 불가 사유 기록률: 100% (해당 시)"}, {"no": 4, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 1", "objective": "초과 사용 업체 대상 제안 방문을 월 2건 이상 진행하고, 방문 후 후속 관리를 한다.", "criteria": "• 9월2주차 초과사용 업체 리스트 확인률: 100%\n• 선정기준(초과사용량/초과금액/계약갱신 가능성 중 2가지 이상 해당) 충족 업체 선정률: 100%\n• 제안 방문: 2건 이상  [건수형]\n• 방문기록(제안내용/고객반응/다음액션) 작성률: 100%\n• 후속 필요 업체의 담당자·진행일정·다음연락시점 수립률: 100%"}, {"no": 5, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 2", "objective": "9월 PC·IT 관리 테마를 정해 고객에게 홍보하고, 고객 반응을 기록한다.", "criteria": "• 9월 홍보테마 선정: 1개  [건수형]\n• 홍보자료·안내멘트 준비: 1개 이상  [건수형]\n• 고객반응 3분류 기록률: 100%\n     └ 필수 기재 → 관심 있음 ○건 / 추후 검토 ○건 / 필요 없음 ○건\n• 파트별 홍보사례 공유: 1건 이상  [건수형]\n• [차월반영] 반응 좋았던 멘트 타 파트 공유: 1건 이상  [건수형]"}, {"no": 6, "pillar": "Pillar 2.\n매출증대 · 안정", "bottleneck": "병목현상 3", "objective": "계약 완료 건은 계약서 작성 확인까지 100% 완료한다.", "criteria": "• 계약완료 건 대비 계약서 작성 확인률: 100%\n• 발송 후 1주일(7일) 이내 작성완료 여부 확인 이행률: 100%\n• 미작성 건 주1회 재확인 이행률: 100%\n• 월말 대사(계약완료 건수 vs 계약서 작성완료 건수) 완료  [건수형]\n• 누락 건 업체명·누락사유·다음조치 기록률: 100% (해당 시)"}, {"no": 7, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 1", "objective": "IT 레벨 3 실습을 이어가고, PC·IT 처리 사례를 월 1건 이상 공유한다.", "criteria": "• 파트별 주1회 학습/실습 진행률: 100% (4주/4주)\n• 월1회 IT 레벨3 체크리스트 진행상황 확인: 완료  [건수형]\n• PC·IT 처리사례 공유: 1건 이상  [건수형]\n• 사례 형식(현장문제/조치방법/결과/배운점) 준수율: 100%\n• [차월반영] 어려웠던 사례를 9월 교육주제로 등록: 1건 이상  [건수형]"}, {"no": 8, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 2", "objective": "각 인원이 주 2개 이상 블로그 답글을 작성하고, 참여 현황을 꾸준히 유지한다.", "criteria": "• 인당 주 답글: 2개 이상\n• 인원별 주2개 달성 참여율: 100% (미달 시 인원별 실적 기재)\n• 주1회 파트 현황확인 이행률: 100% (4주/4주)\n• 월말 인원별·파트별 답글 수 집계: 완료  [건수형]\n• 무의미·반복 댓글: 0건\n• [차월반영] 우수 답글 사례 공유: 1건 이상  [건수형]"}, {"no": 9, "pillar": "Pillar 3.\n나의 성장 · 소통", "bottleneck": "병목현상 3", "objective": "소통 문제와 디브리핑 누락 사례를 확인하고, 부파트장 주관 회식을 진행하거나 일정을 확정한다.", "criteria": "• 업무전달 후 이해 재확인 이행률: 100%\n• 파트별 주간 병목현상 점검: 1주/1주\n• 월1회 소통·디브리핑 누락사례 확인: 완료  [건수형]\n• 누락사례 원인 및 개선안 작성률: 100% (해당 시)\n• 부파트장 주관 회식: 8월 진행 완료 또는 9월 전 일정 확정  [건수형]"}]$okr$::jsonb, $okr${}$okr$::jsonb),
