-- OKR 초기 데이터(선택) — 8월 OKR(목표 9개 · A~D파트 결과 · 팀장 피드백) · 9월 목표 · 9월 2주차 C파트 실행결과 (2026-09-24)
-- okr.sql(표) 실행 뒤에. 앱 OKR 탭의 [엑셀 데이터 불러오기] 버튼과 같은 내용이라 둘 중 하나만 하면 된다. 이미 있으면 건너뜀.

on conflict (id) do nothing;

on conflict (cycle_id, team, member) do nothing;

select c.id, c.kind, c.title, jsonb_array_length(c.goals) as goals, count(r.team) as reports from public.okr_cycles c left join public.okr_reports r on r.cycle_id = c.id group by c.id order by c.start_date desc;
